// Public TypeScript surface for the whiteout-wasm package.
//
// Format-specific types are autogenerated under ./types/. This file is
// hand-written and bolts the WhiteoutAPI interface (the return value of
// the Whiteout() entrypoint) on top of those.

import type * as mdx from "./types/mdx";
import type * as m2  from "./types/m2";
import type * as m3  from "./types/m3";
import type * as textures from "./types/textures";

import type {
    EmbindObject, EmbindVector, EnumValue,
    Vector2f, Vector3f, Vector4f, Quaternion, Texture,
} from "./types/_shared";

export {
    // Generated namespaces — re-exported for type-only consumers.
    mdx, m2, m3, textures,
    // Shared building blocks.
    EmbindObject, EmbindVector, EnumValue,
    Vector2f, Vector3f, Vector4f, Quaternion, Texture,
};


// ── In-memory virtual filesystem (for M2 sibling files) ──────────────────

export interface InMemoryFileSystem extends EmbindObject {
    addFile(path: string, data: Uint8Array): void;
    removeFile(path: string): void;
    clear(): void;
    fileCount(): number;
    fileExists(path: string): boolean;
}

export interface InMemoryFileSystemConstructor {
    new(): InMemoryFileSystem;
}


// ── Texture format facade (one per file format) ──────────────────────────

export interface TextureFormat<P extends EmbindObject, W extends EmbindObject,
                               PMode extends EnumValue, WMode extends EnumValue> {
    /** Raw Embind constructor for the parser class. */
    Parser: new (mode?: PMode) => P;
    /** Raw Embind constructor for the writer class. */
    Writer: new () => W;
    /** Available parse-mode enum values. */
    ParseMode: Record<string, PMode>;
    /** Available write-mode enum values. */
    WriteMode: Record<string, WMode>;
    /** Decode bytes into a Texture. The caller is responsible for
     *  `texture.delete()` once done. */
    parse(bytes: Uint8Array, mode?: PMode): Texture;
    /** Encode a Texture into bytes. */
    write(texture: Texture): Uint8Array;
}

export type BlpFormat  = TextureFormat<textures.BlpParser,  textures.BlpWriter,
                                       EnumValue, EnumValue>;
export type DdsFormat  = TextureFormat<textures.DdsParser,  textures.DdsWriter,
                                       EnumValue, EnumValue>;
export type PngFormat  = TextureFormat<textures.PngParser,  textures.PngWriter,
                                       EnumValue, EnumValue>;
export type JpegFormat = TextureFormat<textures.JpegParser, textures.JpegWriter,
                                       EnumValue, EnumValue>;
export type BmpFormat  = TextureFormat<textures.BmpParser,  textures.BmpWriter,
                                       EnumValue, EnumValue>;
export type TgaFormat  = TextureFormat<textures.TgaParser,  textures.TgaWriter,
                                       EnumValue, EnumValue>;


// ── Per-format model namespaces (types + parse/write helpers) ────────────

/** MDX namespace: every generated MDX type/enum/constant, plus convenience
 *  parse/write functions wrapping the underlying Parser/Writer classes. */
export interface MdxNamespace extends Omit<typeof mdx, never> {
    /** Parse binary MDX bytes. */
    parse(bytes: Uint8Array, mode?: EnumValue, upgrade?: EnumValue): mdx.Model;
    /** Parse text MDL bytes. */
    parseMdl(bytes: Uint8Array, mode?: EnumValue, upgrade?: EnumValue): mdx.Model;
    /** Encode as binary MDX. */
    write(model: mdx.Model): Uint8Array;
    /** Encode as text MDL. */
    writeMdl(model: mdx.Model): Uint8Array;
}

export interface M2Namespace extends Omit<typeof m2, never> {
    /** Parse a M2 model. The first arg is a path -> bytes map of every
     *  sibling file the parser may need (.skin, .skel, .anim, .bone). */
    parse(files: Record<string, Uint8Array>, mainPath: string,
          mode?: EnumValue): m2.Model;
}

export interface M3Namespace extends Omit<typeof m3, never> {
    parse(bytes: Uint8Array, mode?: EnumValue): m3.Model;
    write(model: m3.Model): Uint8Array;
}


// ── Top-level API ────────────────────────────────────────────────────────

export interface WhiteoutAPI {
    /** Combine Embind enum values (or raw integers) into a u32 bitmask.
     *  Use this instead of `a | b` because Embind enum wrappers don't
     *  support direct bitwise operators. */
    flags(...values: Array<number | EnumValue>): number;

    /** Raw Embind module — escape hatch for anything not surfaced by the
     *  facade. */
    module: any;

    // ── Shared types (constructors / value classes / enums) ──────────────
    Texture:     new () => Texture;
    PixelFormat: typeof textures.PixelFormat;
    TextureType: typeof textures.TextureType;
    Vector2f:    new () => Vector2f;
    Vector3f:    new () => Vector3f;
    Vector4f:    new () => Vector4f;
    Quaternion:  new () => Quaternion;
    InMemoryFileSystem: InMemoryFileSystemConstructor;

    /** Math-type factories — sugar for the value_object literal pattern.
     *  `whiteout.vec3(1, 2, 3)` is equivalent to `{ x: 1, y: 2, z: 3 }`. */
    vec2(x: number, y: number): Vector2f;
    vec3(x: number, y: number, z: number): Vector3f;
    vec4(x: number, y: number, z: number, w: number): Vector4f;
    quat(x: number, y: number, z: number, w: number): Quaternion;

    // ── Per-format facades ───────────────────────────────────────────────
    blp:  BlpFormat;
    dds:  DdsFormat;
    png:  PngFormat;
    jpeg: JpegFormat;
    bmp:  BmpFormat;
    tga:  TgaFormat;

    mdx: MdxNamespace;
    m2:  M2Namespace;
    m3:  M3Namespace;
    wem: { parse(bytes: Uint8Array, mode?: EnumValue): EmbindObject;
           write(model: EmbindObject): Uint8Array; }
         & { [k: string]: any };
}

/** Asynchronously instantiate the WASM module and return the facade. */
export function Whiteout(): Promise<WhiteoutAPI>;
export default Whiteout;
